export const coPath = (c) => `/corporate-car-rental/${c.slug}`;
export const coFor = (slug) => COMPANIES.find((c) => c.slug === slug);
export const coInGroup = (key) => COMPANIES.filter((c) => c.group === key);
export const groupOf = (c) => CO_GROUPS[c.group];
export const ALL_CO_PATHS = [CO_HUB.path, ...Object.values(CO_GROUPS).map((g) => g.path), ...COMPANIES.map(coPath)];

// short names used in page titles (kept under the 65-character title limit with the brand)
const SHORT = { "pakistan-petroleum-limited": "PPL", "pakistan-oilfields-limited": "POL", "sngpl": "SNGPL", "ssgc": "SSGC", "pakistan-state-oil": "PSO", "asian-development-bank-pakistan": "ADB Pakistan", "international-rescue-committee-pakistan": "IRC Pakistan", "save-the-children-pakistan": "Save the Children" };
COMPANIES.forEach((c) => { c.short = SHORT[c.slug] || c.name; });
export const CO_GENERIC_FAQS = (c) => [
  f(`How do I get a quote for ${c.short} staff or teams?`, `Call or WhatsApp 0300 9040006 or use the Book Now form. Send the organisation or project name, the vehicles you need, the start date, the duration, the working hours and the routes. We reply with a written quote that states what is included.`),
  f(`Is a driver included with every vehicle for ${c.short} teams?`, `Yes. Every vehicle is provided with an experienced professional driver. We do not offer self-drive, and on monthly contracts the same driver can stay with your team.`),
  f(`Which vehicles can ${c.short} teams rent from you?`, `The full fleet: Premium Luxury Land Cruiser, Land Cruiser V8, Lexus LX 570, Prado, Toyota Fortuner, Hilux Revo, Honda Civic, Toyota Corolla Grande, Mercedes G Wagon, Audi, Range Rover and Toyota Coaster, depending on availability for your dates.`),
];
